  type: "object",
  required: ["answer", "evidence"],
  additionalProperties: false,
  properties: {
    answer: { type: "string" },
    evidence: { type: "array", items: { type: "string" } }
  }
};

subagent({
  async: false,
  context: "fresh",
  cwd: "/workspace/project",
  chain: [{
    parallel: [{
      agent: "delegate",
      output: `${REPORT_DIR}/wave-task1-source-facts.md`,
      outputMode: "file-only",
      outputSchema: ANSWER_SCHEMA,
      task: `Resolve static repair context only.
planPath: /workspace/project/doc/plans/feature.md
anchor: "### Task 1:"
Spec: /workspace/project/doc/specs/feature.md
Owning checkout: /workspace/project
Read the selected anchored task and its cited spec/rules yourself.
Return its mode, Files ownership, exact Tests command array, Leg and combined Rules.
Do not read or relay review reports. Do not reconstruct dynamic wave state.
